// ratelimit/bucket.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a TokenBucket. rate is tokens/second, capacity is the
// maximum burst size. Both must be positive; clock must not be nil.
func NewTokenBucket(rate, capacity float64, clock Clock) (*TokenBucket, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &TokenBucket{
		capacity: capacity,
		tokens:   capacity,
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if allowed.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	tb.tokens += elapsed * tb.rate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is shorthand for AllowN(1).
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
